<?php

declare(strict_types=1);

if (! function_exists('timb_manifest')) {
    /** Generated by tools/optimize_images.py. */
    function timb_manifest(): array
    {
        static $manifest = null;

        return $manifest ??= require APPPATH . 'Data/ImageManifest.php';
    }
}

if (! function_exists('img_url')) {
    function img_url(string $key, string $size = '640'): string
    {
        return base_url("assets/img/machines/{$key}-{$size}.webp");
    }
}

if (! function_exists('img_tag')) {
    /** <img> with intrinsic width/height (prevents layout shift). $attrs are escaped. */
    function img_tag(string $key, string $size, string $alt, array $attrs = []): string
    {
        $dims = timb_manifest()[$key]['files'][$size] ?? null;
        if ($dims === null) {
            log_message('error', "Unknown image key: {$key} ({$size})");

            return '';
        }

        $attrs = ['src' => img_url($key, $size), 'alt' => $alt, 'width' => $dims[0], 'height' => $dims[1], 'decoding' => 'async'] + $attrs;
        $html  = '';
        foreach ($attrs as $name => $value) {
            $html .= ' ' . $name . '="' . esc((string) $value, 'attr') . '"';
        }

        return '<img' . $html . '>';
    }
}

if (! function_exists('asset_url')) {
    /** Public asset URL with ?v=<mtime> cache-busting. */
    function asset_url(string $path): string
    {
        $file = FCPATH . ltrim($path, '/');

        return base_url($path) . (is_file($file) ? '?v=' . filemtime($file) : '');
    }
}

if (! function_exists('india_xy')) {
    /**
     * Lat/lon -> [x%, y%] inside the India map SVG (see partials/india_map.php).
     * Map bounds: lon 68.0–97.6, lat 6.5–37.3.
     */
    function india_xy(float $lat, float $lon): array
    {
        return [round(($lon - 68.0) / 29.6 * 100, 2), round((37.3 - $lat) / 30.8 * 100, 2)];
    }
}
